(function(root){"use strict";root.SDAkademieKurse=root.SDAkademieKurse||Object.create(null);root.SDAkademieKurse["javascript"]=[{"id":"p3-1","title":"Datentypen","minutes":25,"ziel":"Zahlen, Text und Boolean unterscheiden","schritte":[{"titel":"Zahlen ohne Anführungszeichen","text":"Eine Zahl wie 12 lässt sich direkt berechnen. Ohne Anführungszeichen speichert JavaScript einen numerischen Wert. Für einen festen Preis ist const geeignet. Ein Preisetikett trägt eine Zahl, nicht den geschriebenen Namen der Zahl. Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`. So erkennst du am Ergebnis, ob JavaScript rechnet oder Text verbindet.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"Zeile 1 legt preis mit `const` fest; Zeile 2 legt ort als Zeichenkette an. Vergleiche `12 + 3` mit `'12' + 3` und beobachte `15` gegenüber `123`."},{"titel":"Strings als Textwerte","text":"Ein Ortsname wird als String gespeichert. Dafür schreibst du den Text zwischen Anführungszeichen. Mit einem Pluszeichen lassen sich zwei Strings verbinden. Eine Postkarte enthält Buchstaben und wird nicht wie ein Geldbetrag addiert. `const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole. Setze statt Bonn deinen eigenen Wohnort ein und behalte die Anführungszeichen.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`const ort = 'Bonn';` bindet den Text Bonn an den Namen ort. `console.log(ort)` schreibt diesen Text in die Entwicklerkonsole."},{"titel":"Boolean true und false","text":"Ein Boolean ist entweder true oder false. Er steht ohne Anführungszeichen im Code. So kannst du Zustände wie offen oder geschlossen speichern. Ein Lichtschalter hat zwei Zustände; Boolean bildet genau diese Unterscheidung ab. `const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen. Probiere danach `false` und prüfe, ob der Zweig übersprungen wird.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`const offen = true;` legt einen echten Wahrheitswert an. `if (offen)` kann damit eine Entscheidung treffen, ohne Text zu vergleichen."},{"titel":"Mit typeof kontrollieren","text":"typeof zeigt den Typ eines Werts an. typeof 12 liefert number, typeof '12' liefert string. Teste den Unterschied in der Konsole. Ein Etikett am Vorratsglas sagt dir, was darin liegt; `typeof` übernimmt diese Aufgabe für Werte. `console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen. Notiere beide Ergebnisse, bevor du weitere Werte ausprobierst.","code":"const preis = 12; const ort = 'Bonn'; const offen = true;","erklaerung":"`console.log(typeof 12);` zeigt `number` als Typ an. `console.log(typeof '12');` zeigt `string`, obwohl die Zeichen gleich aussehen."}],"beispiel":{"html":"<h1>Datentypen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-1-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-1-js"}],"loesung":{"html":"<h1>Datentypen</h1><p id='ausgabe'></p>","css":"","js":"const preis = 12; const ort = 'Bonn'; const offen = true;"}},"fehler":[{"titel":"Zahl als Text gespeichert","text":"Falsch: `const preis = '12'; console.log(preis + 3);` ergibt `123` statt `15` in der Konsole. Der Preis ist ein String und das Pluszeichen hängt Text an. Richtig: `const preis = 12; console.log(preis + 3);` zeigt `15`."},{"titel":"Boolean fälschlich in Anführungszeichen","text":"Falsch: `const offen = 'false'; if (offen) console.log('offen');` zeigt trotzdem `offen`, weil der nichtleere String als wahr gilt. Richtig: `const offen = false; if (offen) console.log('offen');` zeigt keine Meldung."}],"quiz":[{"frage":"Was ist typeof 12?","antworten":["string","number","boolean"],"richtig":1,"erklaerung":"Hier passt „number“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was ist typeof '12'?","antworten":["number","boolean","string"],"richtig":2,"erklaerung":"Hier passt „string“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]},{"frage":"Welcher Wert ist ein Boolean?","antworten":["true","'true'","12"],"richtig":0,"erklaerung":"Hier passt „true“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]}],"merke":["Bei Datentypen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const preis = 12; const ort = 'Bonn'; const offen = true;` als Vergleich für deine eigene Übung."]},{"id":"p3-2","title":"Arrays","minutes":25,"ziel":"Mehrere Einträge in einer Liste speichern","schritte":[{"titel":"Eine Einkaufsliste anlegen","text":"Ein Array sammelt mehrere Werte in eckigen Klammern. Trenne die Einträge mit Kommas. So bleibt eine Einkaufsliste in einer einzigen Variablen. Eine Einkaufstasche enthält mehrere Produkte; ein Array hält ihre Namen zusammen. `const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text. Füge probeweise einen dritten Artikel zwischen den Klammern hinzu.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`const einkauf = ['Brot', 'Milch'];` erzeugt zwei Einträge. Die eckigen Klammern gehören zur Liste, die Anführungszeichen zu jedem Text."},{"titel":"Einträge mit Index lesen","text":"Die erste Position eines Arrays hat den Index null. einkauf[0] liefert daher Brot. Der zweite Eintrag wird über einkauf[1] gelesen. Regalfächer haben Nummern; JavaScript beginnt die Nummerierung bei null. `console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach. Ein Zugriff auf `einkauf[9]` liefert dagegen `undefined`.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`console.log(einkauf[0]);` liest Brot aus dem ersten Fach. `console.log(einkauf[1]);` liest Milch aus dem zweiten Fach."},{"titel":"Mit push erweitern","text":"Mit push fügst du einen neuen Eintrag am Ende hinzu. Die vorhandenen Werte bleiben erhalten. Probiere einkauf.push('Reis') in deinem Beispiel aus. Beim Einkaufen legst du neue Waren hinten in die Tasche; so arbeitet push. `einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen. Die Methode braucht runde Klammern und den gewünschten Wert.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`einkauf.push('Reis');` ergänzt den String Reis. `console.log(einkauf);` zeigt danach alle drei Namen."},{"titel":"Die Länge abfragen","text":"length gibt die Anzahl der Einträge zurück. Nach dem Hinzufügen sind es drei. Verwende die Eigenschaft ohne Klammern. Ein Kassenbon zählt Positionen, nicht den letzten Regalindex. `console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben. Lösche testweise einen Eintrag und vergleiche die neue Anzahl.","code":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);","erklaerung":"`console.log(einkauf.length);` liefert nach push den Wert drei. Die Eigenschaft length wird ohne `()` geschrieben."}],"beispiel":{"html":"<h1>Einkaufsliste</h1><ul id='liste'></ul>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-2-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-2-js"}],"loesung":{"html":"<h1>Einkaufsliste</h1><ul id='liste'></ul>","css":"","js":"const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);"}},"fehler":[{"titel":"Ersten Eintrag mit Index eins gesucht","text":"Falsch: `console.log(einkauf[1]);` zeigt `Milch`, obwohl du `Brot` erwartest. Arrays zählen ab null. Richtig: `console.log(einkauf[0]);` zeigt `Brot`."},{"titel":"push ohne Argument verwendet","text":"Falsch: `einkauf.push();` fügt einen Eintrag mit dem Wert `undefined` hinzu; die Liste enthält danach keinen neuen Artikelnamen. Richtig: `einkauf.push('Reis');` ergänzt einen sichtbaren Einkauf."}],"quiz":[{"frage":"Welcher Index ist der erste?","antworten":["1","0","2"],"richtig":1,"erklaerung":"Hier passt „0“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie wird Reis angehängt?","antworten":["einkauf.add('Reis')","einkauf[0]","einkauf.push('Reis')"],"richtig":2,"erklaerung":"Hier passt „einkauf.push('Reis')“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]},{"frage":"Was liefert length?","antworten":["Anzahl der Einträge","Ersten Text","Letzten Namen"],"richtig":0,"erklaerung":"Hier passt „Anzahl der Einträge“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]}],"merke":["Bei Arrays ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const einkauf = ['Brot','Milch']; einkauf.push('Reis'); console.log(einkauf.length);` als Vergleich für deine eigene Übung."]},{"id":"p3-3","title":"Schleifen","minutes":25,"ziel":"Wiederholungen mit for und for...of schreiben","schritte":[{"titel":"Wiederholung verstehen","text":"Eine Schleife führt denselben Ablauf mehrmals aus. Du musst die Anweisung nicht kopieren. Das ist bei einer Liste von Namen besonders praktisch. Eine Lehrkraft ruft alle Namen der Anwesenheitsliste nacheinander auf. `for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt. So bleiben auch längere Listen ohne kopierte Ausgaben übersichtlich.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`for (const name of namen)` besucht jeden vorhandenen Eintrag. Der Block in geschweiften Klammern wird für jeden Namen wiederholt."},{"titel":"for...of für Arrays","text":"for...of liest die Einträge nacheinander. Der Name im Schleifenkopf steht jeweils für den aktuellen Eintrag. Innerhalb der Klammern kannst du ihn ausgeben. Wie bei einer Runde durch mehrere Zimmer wird derselbe Arbeitsschritt wiederholt. `console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch. Prüfe die Ausgabe mit einer Liste aus drei Personen.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`console.log(name);` verwendet im Block den jeweils aktuellen Namen. Nach dem letzten Eintrag endet for...of automatisch."},{"titel":"Zähler mit let verwenden","text":"Eine klassische for-Schleife benutzt oft let i = 0. Nach jedem Durchlauf erhöht i++ den Zähler. Mit i < 3 läuft der Block genau dreimal. Eine Nummernausgabe am Schalter zählt 0, 1, 2 und stoppt dann. `let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins. Ändere die Grenze auf vier und kontrolliere die zusätzliche Ausgabe.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"`let i = 0` setzt den Anfangswert, `i < 3` prüft die Grenze. `i++` erhöht die Nummer nach jedem Durchlauf um eins."},{"titel":"Abbruchbedingung prüfen","text":"Eine Schleife braucht eine erreichbare Abbruchbedingung. Ohne Änderung des Zählers kann sie endlos laufen. Prüfe den Ablauf zunächst mit wenigen Werten. Eine Rolltreppe ohne Ausgang wäre gefährlich; eine Schleife ohne Ende blockiert den Ablauf. Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr. Nutze zuerst kurze Listen, um versehentliche Dauerschleifen zu erkennen.","code":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }","erklaerung":"Bei `for (let i = 0; i < 3; i++)` ist das Ende erreichbar. Wenn `i++` fehlt, bleibt die Bedingung dauerhaft wahr."}],"beispiel":{"html":"<h1>Schleifen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-3-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-3-js"}],"loesung":{"html":"<h1>Schleifen</h1><p id='ausgabe'></p>","css":"","js":"const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }"}},"fehler":[{"titel":"Zähler wird nicht erhöht","text":"Falsch: `for (let i = 0; i < 3;) console.log(i);` bleibt bei null und kann den Browser blockieren. Der Zähler ändert sich nie. Richtig: `for (let i = 0; i < 3; i++) console.log(i);` gibt `0`, `1`, `2` aus."},{"titel":"Index läuft über das Arrayende","text":"Falsch: `for (let i = 0; i <= namen.length; i++) console.log(namen[i]);` gibt am Ende `undefined` aus. Der letzte gültige Index ist kleiner als length. Richtig: `for (let i = 0; i < namen.length; i++) console.log(namen[i]);`."}],"quiz":[{"frage":"Was macht for...of?","antworten":["Löscht Elemente","Liest Einträge nacheinander","Öffnet eine Webseite"],"richtig":1,"erklaerung":"Hier passt „Liest Einträge nacheinander“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie viele Durchläufe hat i < 3 ab null?","antworten":["Drei","Vier","Zwei"],"richtig":0,"erklaerung":"Hier passt „Drei“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was vermeidet eine Endlosschleife?","antworten":["Längere Namen","Mehr Farben","Erreichbare Abbruchbedingung"],"richtig":2,"erklaerung":"Hier passt „Erreichbare Abbruchbedingung“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Schleifen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const namen = ['Ali','Mina']; for (const name of namen) { console.log(name); }` als Vergleich für deine eigene Übung."]},{"id":"p3-4","title":"Funktionen","minutes":25,"ziel":"Eigene Funktionen mit Parametern und return nutzen","schritte":[{"titel":"Funktion benennen","text":"Eine Funktion bündelt einen wiederkehrenden Ablauf. function leitet die Definition ein. Der Name beschreibt die Aufgabe möglichst genau. Eine Kaffeemaschine erledigt nach dem Start immer dieselben Schritte. `function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung. Ein bloßes Definieren startet die Maschine noch nicht.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`function doppelt(zahl)` gibt dem Ablauf einen Namen und einen Parameter. Die geschweiften Klammern umschließen die Rechenanweisung."},{"titel":"Parameter entgegennehmen","text":"In runden Klammern stehen Parameter. Beim Aufruf wird für jeden Parameter ein Wert übergeben. Im Funktionskörper kannst du damit rechnen. Eine Bestellung nennt die gewünschte Menge; ein Parameter übernimmt diesen Wert. `doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert. Rufe anschließend doppelt mit sechs auf und vergleiche die Ergebnisse.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`doppelt(4)` übergibt die Zahl vier an den Parameter zahl. Im Funktionskörper steht dann für zahl genau dieser Wert."},{"titel":"Ergebnis zurückgeben","text":"return liefert ein Ergebnis an den Aufrufer. Eine reine Konsolenausgabe gibt dagegen nicht automatisch einen Wert zurück. Nutze return für weitere Berechnungen. Ein Automat gibt nach dem Einwurf etwas zurück; return ist diese Rückgabe. `return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht. Ohne return erhält der Aufrufer den Wert `undefined`.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"`return zahl * 2;` berechnet und liefert das Ergebnis. `console.log` kann es anschließend sichtbar machen, ersetzt return aber nicht."},{"titel":"Funktion aufrufen","text":"Die Definition allein führt den Code noch nicht aus. Erst doppelt(4) startet den Ablauf. Das Ergebnis dieser Rechnung ist acht. Ein beschrifteter Werkzeugkasten lässt dich ein Werkzeug schnell wiederfinden. Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht. Verwende denselben Funktionsnamen beim Definieren und Aufrufen.","code":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));","erklaerung":"Der Name doppelt beschreibt die Rechnung besser als ein beliebiger Buchstabe. `console.log(doppelt(4));` startet den Aufruf und zeigt acht."}],"beispiel":{"html":"<h1>Funktionen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-4-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-4-js"}],"loesung":{"html":"<h1>Funktionen</h1><p id='ausgabe'></p>","css":"","js":"function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));"}},"fehler":[{"titel":"Funktion nicht aufgerufen","text":"Falsch: `function doppelt(x) { return x * 2; }` allein erzeugt keine Ausgabe; die Funktion wurde noch nicht gestartet. Richtig: `console.log(doppelt(4));` ruft sie auf und zeigt `8`."},{"titel":"console.log mit return verwechselt","text":"Falsch: `function doppelt(x) { console.log(x * 2); } console.log(doppelt(4));` zeigt zuerst `8`, dann `undefined`. console.log zeigt nur etwas an, gibt aber keinen Rückgabewert zurück. Richtig: `function doppelt(x) { return x * 2; } console.log(doppelt(4));` zeigt nur `8`."}],"quiz":[{"frage":"Wozu dient ein Parameter?","antworten":["Zum Löschen","Für Eingabewerte","Für CSS"],"richtig":1,"erklaerung":"Hier passt „Für Eingabewerte“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was macht return?","antworten":["Gibt ein Ergebnis zurück","Startet HTML","Öffnet eine Datei"],"richtig":0,"erklaerung":"Hier passt „Gibt ein Ergebnis zurück“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wann läuft die Funktion?","antworten":["Beim Speichern","Beim Benennen","Beim Aufruf"],"richtig":2,"erklaerung":"Hier passt „Beim Aufruf“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Funktionen ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `function doppelt(zahl) { return zahl * 2; } console.log(doppelt(4));` als Vergleich für deine eigene Übung."]},{"id":"p3-5","title":"Objekte","minutes":25,"ziel":"Zusammengehörige Eigenschaften verwalten","schritte":[{"titel":"Personendaten bündeln","text":"Ein Objekt speichert zusammengehörige Angaben. Zwischen geschweiften Klammern stehen Eigenschaft und Wert. Ein Doppelpunkt trennt beide Teile. Eine Kontaktkarte hält Name und Ort einer Person beisammen. `const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert. Die Kommas trennen die Angaben innerhalb des Objekts.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`const person = { name: 'Amina', ort: 'Bonn' };` erstellt zwei Eigenschaften. Der Doppelpunkt verbindet jeweils Schlüssel und Wert."},{"titel":"Eigenschaften mit Punkt lesen","text":"Mit person.name liest du eine Eigenschaft. Du brauchst dafür keine zusätzliche Variable. Der Punkt verbindet den Objektnamen mit dem Eigenschaftsnamen. Auf einer Karte suchst du die Zeile Name, nicht die ganze Karte. `person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole. Schreibst du versehentlich Name groß, erhältst du möglicherweise undefined.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.name` liest nur den gespeicherten Namen. `console.log(person.name);` zeigt ihn in der Konsole."},{"titel":"Eigenschaften ändern","text":"Eine Eigenschaft lässt sich mit person.ort = 'Köln' ändern. Das ist auch bei einem mit const angelegten Objekt erlaubt. Die gesamte Variable darf jedoch nicht neu zugewiesen werden. Eine Adresse auf einer Kontaktkarte darf sich nach einem Umzug ändern. `person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt. Prüfe die Änderung mit einer anschließenden Konsolenausgabe.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.ort = 'Köln';` ersetzt nur den Wert der Eigenschaft ort. Die Variable person bleibt weiterhin dasselbe Objekt."},{"titel":"Fehlende Werte erkennen","text":"Ein falsch geschriebener Eigenschaftsname liefert oft undefined. Prüfe die genaue Schreibweise. Gleiche Namen machen mehrere Objekte leichter vergleichbar. Fehlt ein Feld auf einer Karte, kannst du seinen Inhalt nicht lesen. `person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen. Du kannst `person.alter = 30` ergänzen und danach erneut lesen.","code":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);","erklaerung":"`person.alter` liefert undefined, wenn alter nicht existiert. Prüfe die Schreibweise der Eigenschaft vor weiteren Berechnungen."}],"beispiel":{"html":"<h1>Objekte</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-5-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-5-js"}],"loesung":{"html":"<h1>Objekte</h1><p id='ausgabe'></p>","css":"","js":"const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);"}},"fehler":[{"titel":"Eigenschaftsname falsch geschrieben","text":"Falsch: `console.log(person.Name);` liefert `undefined`, obwohl `name` gespeichert ist. Eigenschaftsnamen unterscheiden Groß- und Kleinschreibung. Richtig: `console.log(person.name);` zeigt `Amina`."},{"titel":"const-Objekt neu zugewiesen","text":"Falsch: `const person = { name: 'Amina' }; person = { name: 'Mina' };` erzeugt `TypeError: Assignment to constant variable.`. Du darfst die const-Bindung nicht ersetzen. Richtig: `person.name = 'Mina';` ändert die Eigenschaft."}],"quiz":[{"frage":"Was liefert person.name?","antworten":["Ort","Name","Objektlänge"],"richtig":1,"erklaerung":"Hier passt „Name“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was bedeutet undefined?","antworten":["Wert fehlt möglicherweise","Alles ist gelöscht","Wert ist null"],"richtig":0,"erklaerung":"Hier passt „Wert fehlt möglicherweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was darfst du ändern?","antworten":["const person neu setzen","const entfernen","person.ort"],"richtig":2,"erklaerung":"Hier passt „person.ort“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Objekte ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const person = { name: 'Amina', ort: 'Bonn' }; console.log(person.name);` als Vergleich für deine eigene Übung."]},{"id":"p3-6","title":"DOM","minutes":25,"ziel":"HTML-Elemente finden und sicher verändern","schritte":[{"titel":"DOM als Dokumentstruktur","text":"Der Browser stellt HTML als Dokumentstruktur bereit. Diese Struktur heißt DOM. JavaScript kann darin gezielt Elemente suchen. Ein Stadtplan zeigt Straßen und Häuser; das DOM bildet die Struktur einer Webseite ab. `document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst. Lege ein `<p id='ausgabe'>` an, damit die Suche erfolgreich ist.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`document.querySelector('#ausgabe')` sucht die passende ID. Das Zeichen # bedeutet, dass du ein bestimmtes Element meinst."},{"titel":"Element per ID auswählen","text":"querySelector findet ein Element anhand eines CSS-Selektors. Das Zeichen # steht für eine ID. Stimmen die Namen nicht überein, kommt null zurück. Eine Hausnummer muss genau stimmen, sonst findest du das Gebäude nicht. `const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null. Prüfe den Namen im HTML und im JavaScript Zeichen für Zeichen.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`const ausgabe = document.querySelector('#ausgabe');` speichert das gefundene Element. Ist die ID anders geschrieben, steht in ausgabe der Wert null."},{"titel":"textContent einsetzen","text":"textContent ersetzt den sichtbaren Text. Anders als innerHTML behandelt es Nutzereingaben nicht als HTML-Markup. Das hilft gegen unerwünschte Codeausführung. Ein Hinweisschild kann einen neuen Text bekommen, ohne dass du das ganze Schild austauschst. `ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt. Das ist wichtig, wenn später fremde Eingaben angezeigt werden.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`ausgabe.textContent = 'Willkommen';` ersetzt den sichtbaren Inhalt. Auch Zeichen wie `<` werden dabei als Text behandelt."},{"titel":"Auf Existenz prüfen","text":"Prüfe das Element vor dem Zugriff. Eine einfache if-Abfrage verhindert Fehler bei null. Platziere das Skript so, dass das HTML bereits geladen wurde. Ein Briefkasten muss montiert sein, bevor du einen Brief einwerfen kannst. `if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent. Teste den Fall einer absichtlich falschen ID ohne Browserabsturz.","code":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';","erklaerung":"`if (ausgabe)` prüft, ob das Element gefunden wurde. Erst im erfolgreichen Zweig änderst du textContent."}],"beispiel":{"html":"<h1>DOM</h1><p id='ausgabe'>Vorher</p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-6-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-6-js"}],"loesung":{"html":"<h1>DOM</h1><p id='ausgabe'>Vorher</p>","css":"","js":"const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';"}},"fehler":[{"titel":"ID im HTML stimmt nicht","text":"Falsch: `document.querySelector('#anzeige').textContent = 'Hallo';` kann `TypeError: Cannot set properties of null` auslösen, wenn das HTML nur `id='ausgabe'` enthält. Richtig: `document.querySelector('#ausgabe').textContent = 'Hallo';` trifft das vorhandene Element."},{"titel":"innerHTML für fremde Texte benutzt","text":"Falsch: `ausgabe.innerHTML = eingabe;` kann eingegebenes HTML als echte Elemente darstellen, statt es als Text zu zeigen. Richtig: `ausgabe.textContent = eingabe;` zeigt auch `<b>Hallo</b>` wörtlich an."}],"quiz":[{"frage":"Was findet #ausgabe?","antworten":["Alle Links","Element mit passender ID","Ein Stylesheet"],"richtig":1,"erklaerung":"Hier passt „Element mit passender ID“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was setzt sicheren Text?","antworten":["textContent","innerHTML","eval"],"richtig":0,"erklaerung":"Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was bedeutet null?","antworten":["Leerer Text","Keine CSS-Regel","Kein Element gefunden"],"richtig":2,"erklaerung":"Hier passt „Kein Element gefunden“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei DOM ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Willkommen';` als Vergleich für deine eigene Übung."]},{"id":"p3-7","title":"Events","minutes":25,"ziel":"Klicks mit addEventListener verarbeiten","schritte":[{"titel":"Klick als Ereignis","text":"Ein Event ist ein Ereignis wie ein Klick. JavaScript kann darauf warten. So wird eine Seite interaktiv. Eine Türklingel löst erst beim Drücken ein Signal aus; ein Klick ist ähnlich. `addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt. So bleibt der Knopf für weitere Klicks bereit.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`addEventListener('click', ...)` wartet auf das Ereignis. Die Funktion wird nicht bereits beim Laden der Seite ausgeführt."},{"titel":"Listener registrieren","text":"addEventListener verbindet ein Element mit einer Funktion. Die Funktion wird erst beim Ereignis ausgeführt. Achte auf die Schreibweise click. Ein Empfangsdienst erhält eine Telefonnummer, nicht einen schon beendeten Anruf. `knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen. Achte deshalb darauf, ob hinter dem Funktionsnamen Klammern stehen.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`knopf.addEventListener('click', melden)` übergibt die Funktion selbst. Mit `melden()` würdest du sie bereits beim Registrieren aufrufen."},{"titel":"Rückmeldung zeigen","text":"Im Listener kannst du Text ändern. Eine Meldung wie Gespeichert bestätigt die Aktion. Das ist für Nutzerinnen und Nutzer eine wichtige Rückmeldung. Eine Quittung bestätigt eine Zahlung; ein Statussatz bestätigt einen Klick. `ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion. Klicke zweimal und kontrolliere, dass die Meldung verständlich bleibt.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"`ausgabe.textContent = 'Gespeichert';` aktualisiert die Meldung. Die Änderung erfolgt innerhalb der Klick-Funktion."},{"titel":"Tastatur prüfen","text":"Ein echtes button-Element funktioniert auch mit der Tastatur. Teste Tab und Enter. Ein klickbarer Absatz ist dafür keine gleichwertige Lösung. Eine barrierefreie Tür lässt sich auf mehreren Wegen öffnen. Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter. Ein bloßer div ohne zusätzliche Tastaturbehandlung reicht dafür nicht.","code":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });","erklaerung":"Ein HTML-button reagiert neben der Maus auch auf Tastatureingaben. Erreiche den Knopf mit Tab und aktiviere ihn mit Enter."}],"beispiel":{"html":"<h1>Events</h1><button id='knopf' type='button'>Speichern</button><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-7-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-7-js"}],"loesung":{"html":"<h1>Events</h1><button id='knopf' type='button'>Speichern</button><p id='ausgabe'></p>","css":"","js":"const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });"}},"fehler":[{"titel":"Funktion sofort statt beim Klick ausgeführt","text":"Falsch: `knopf.addEventListener('click', melden());` ruft melden sofort auf; beim Klick passiert danach nichts oder ein TypeError entsteht. Richtig: `knopf.addEventListener('click', melden);` übergibt die Funktion ohne Klammern."},{"titel":"Listener an null registriert","text":"Falsch: `document.querySelector('#knop').addEventListener('click', melden);` löst `TypeError: Cannot read properties of null` aus, wenn der Knopf `id='knopf'` heißt. Richtig: `document.querySelector('#knopf').addEventListener('click', melden);`."}],"quiz":[{"frage":"Wie heißt das Klick-Ereignis?","antworten":["submit","click","change"],"richtig":1,"erklaerung":"Hier passt „click“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was registriert einen Listener?","antworten":["addEventListener","querySelectorAll","textContent"],"richtig":0,"erklaerung":"Hier passt „addEventListener“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Warum button verwenden?","antworten":["Es lädt schneller","Es braucht kein CSS","Es ist per Tastatur bedienbar"],"richtig":2,"erklaerung":"Hier passt „Es ist per Tastatur bedienbar“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Events ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const knopf = document.querySelector('#knopf'); const ausgabe = document.querySelector('#ausgabe'); if (knopf && ausgabe) knopf.addEventListener('click', () => { ausgabe.textContent = 'Gespeichert'; });` als Vergleich für deine eigene Übung."]},{"id":"p3-8","title":"Konsole","minutes":25,"ziel":"JavaScript-Fehler systematisch untersuchen","schritte":[{"titel":"Werte protokollieren","text":"console.log zeigt Werte in der Entwicklerkonsole. Damit erkennst du Zwischenergebnisse. Beschrifte deine Ausgaben verständlich. Ein Techniker liest die Anzeige eines Geräts, bevor er etwas austauscht. `console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um. So erkennst du, ob die Suche überhaupt erfolgreich war.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`console.log('Gefunden:', Boolean(element));` zeigt einen beschrifteten Wert. Boolean wandelt die Existenz des Elements in true oder false um."},{"titel":"SyntaxError erkennen","text":"Ein SyntaxError weist auf ungültige Schreibweise hin. Prüfe Klammern und Anführungszeichen. Die Zeilennummer hilft beim Suchen. Ein falsch geschriebenes Wort auf einem Formular verhindert das Verständnis. `console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus. Ergänze `);` und starte die Prüfung erneut.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`console.log('Hallo'` fehlt die schließende runde Klammer. Der Browser meldet einen SyntaxError und führt den Code nicht aus."},{"titel":"TypeError verstehen","text":"Ein TypeError kann bei einem Zugriff auf null entstehen. Kontrolliere das Ergebnis von querySelector. Eine if-Abfrage schützt vor dem Zugriff. Eine Lieferung an eine unbekannte Adresse kann nicht ankommen. `document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError. Mit `if (element)` vermeidest du diesen Zugriff.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"`document.querySelector('#fehlt')` liefert null, wenn es kein Ziel gibt. Ein direkter Zugriff auf `.textContent` erzeugt dann einen TypeError."},{"titel":"Gezielt erneut testen","text":"Ändere jeweils nur eine Stelle. Starte danach den Test erneut. Entferne überflüssige Debug-Ausgaben vor der Veröffentlichung. Beim Reparieren eines Fahrrads prüfst du nach jeder Änderung nur das betroffene Teil. Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung. Wiederhole den Test, bis die Fehlermeldung verschwindet.","code":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));","erklaerung":"Setze eine beschriftete console.log-Ausgabe vor den verdächtigen Abschnitt. Beobachte den Wert und ändere danach genau eine Anweisung."}],"beispiel":{"html":"<h1>Konsole</h1><p id='ausgabe'>Prüfen</p>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-8-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-8-js"}],"loesung":{"html":"<h1>Konsole</h1><p id='ausgabe'>Prüfen</p>","css":"","js":"const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));"}},"fehler":[{"titel":"Syntaxfehler überlesen","text":"Falsch: `console.log('Hallo'` erzeugt `SyntaxError: missing ) after argument list` oder eine entsprechende Syntaxmeldung. Die schließende Klammer fehlt. Richtig: `console.log('Hallo');` lässt sich ausführen."},{"titel":"Auf null ohne Prüfung zugegriffen","text":"Falsch: `document.querySelector('#fehlt').textContent = 'OK';` löst `TypeError: Cannot set properties of null` aus, wenn es das Element nicht gibt. Richtig: `const el = document.querySelector('#fehlt'); if (el) el.textContent = 'OK';`."}],"quiz":[{"frage":"Was zeigt console.log?","antworten":["Nur Bilder","Werte in der Konsole","Nur HTML"],"richtig":1,"erklaerung":"Hier passt „Werte in der Konsole“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was ist SyntaxError?","antworten":["Ungültige Schreibweise","Fehlendes Internet","Falsche Farbe"],"richtig":0,"erklaerung":"Hier passt „Ungültige Schreibweise“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Was vor textContent prüfen?","antworten":["Schriftgröße","Fensterhöhe","Element ist nicht null"],"richtig":2,"erklaerung":"Hier passt „Element ist nicht null“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Konsole ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const element = document.querySelector('#ausgabe'); console.log('Gefunden:', Boolean(element));` als Vergleich für deine eigene Übung."]},{"id":"p3-9","title":"Projekt: To-do-Liste","minutes":25,"ziel":"Eine kleine Aufgabenliste mit Eingabe und Knopf bauen","schritte":[{"titel":"Eingabe beschriften","text":"Eine Aufgabenliste braucht ein Eingabefeld. Verbinde label und input über for und id. Der Knopf startet das Hinzufügen. Ein Notizblock braucht eine Zeile für jede neue Aufgabe. `<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe. So finden auch Menschen mit Vorleseprogramm das richtige Feld.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`<label for='aufgabe'>` beschreibt das Eingabefeld. Das zugehörige input hat die ID aufgabe."},{"titel":"Leere Aufgaben vermeiden","text":"Mit value liest du die Eingabe. trim entfernt Leerzeichen am Anfang und Ende. Eine leere Eingabe darf keinen Eintrag erzeugen. Auf einem Einkaufszettel hilft eine leere Zeile niemandem. `feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text. Teste Eingaben mit nur drei Leerzeichen und mit einem echten Wort.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`feld.value.trim()` entfernt Leerzeichen am Rand. `if (!text) return;` beendet den Klickablauf bei leerem Text."},{"titel":"Listeneinträge erzeugen","text":"createElement erzeugt ein neues li-Element. Mit textContent setzt du den Aufgabentext sicher. appendChild fügt den Eintrag in die Liste ein. Eine neue Karteikarte wird erst erstellt und danach beschriftet. `document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein. `liste.appendChild(li)` hängt den Eintrag an die sichtbare Liste.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`document.createElement('li')` erzeugt einen Listeneintrag. `li.textContent = text` schreibt die Aufgabe sicher hinein."},{"titel":"Aufgaben nach Klick anzeigen","text":"Leere das Feld nach dem Hinzufügen. Probiere mehrere Aufgaben nacheinander. Kontrolliere die Bedienung auch auf einem kleinen Handy. Nach dem Eintragen einer Aufgabe ist der Stift wieder frei für die nächste. `feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen. Teste zwei unterschiedliche Aufgaben nacheinander.","code":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });","erklaerung":"`feld.value = ''` leert das Eingabefeld nach dem Hinzufügen. Ein erneuter Klick mit leerem Feld darf keinen Eintrag erzeugen."}],"beispiel":{"html":"<h1>Aufgabenliste</h1><label for='aufgabe'>Neue Aufgabe</label><input id='aufgabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":""},"aufgabe":{"text":"Setze das Beispiel im Editor um und kontrolliere die Vorschau oder Konsole.","tipp":"Vergleiche die Schreibweise mit dem Codebeispiel.","pruefungen":[{"beschreibung":"Passende HTML-Struktur vorhanden.","test":"p3-9-html"},{"beschreibung":"JavaScript enthält die geübte Technik.","test":"p3-9-js"}],"loesung":{"html":"<h1>Aufgabenliste</h1><label for='aufgabe'>Neue Aufgabe</label><input id='aufgabe'><button id='hinzufuegen' type='button'>Hinzufügen</button><ul id='liste'></ul>","css":"","js":"const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });"}},"fehler":[{"titel":"Leere Aufgaben gespeichert","text":"Falsch: `aufgaben.push(feld.value);` übernimmt auch `   ` als Aufgabe; in der Vorschau erscheint ein leerer Listeneintrag. Richtig: `const text = feld.value.trim(); if (!text) return; aufgaben.push(text);`."},{"titel":"Eingabetext mit innerHTML eingesetzt","text":"Falsch: `liste.innerHTML += '<li>' + feld.value + '</li>';` interpretiert eingegebenes HTML und kann unerwünschte Elemente erzeugen. Richtig: `const li = document.createElement('li'); li.textContent = feld.value; liste.appendChild(li);`."}],"quiz":[{"frage":"Was entfernt trim?","antworten":["Rand-Leerzeichen","Alle Zahlen","Alle Einträge"],"richtig":0,"erklaerung":"Hier passt „Rand-Leerzeichen“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie erzeugst du li?","antworten":["querySelector","createElement","addEventListener"],"richtig":1,"erklaerung":"Hier passt „createElement“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion."]},{"frage":"Wie zeigst du Text sicher?","antworten":["eval","innerHTML","textContent"],"richtig":2,"erklaerung":"Hier passt „textContent“, weil es die im Beispiel geübte Aufgabe richtig beschreibt.","begruendungen":["Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt nicht die gesuchte Funktion.","Diese Antwort beschreibt die gesuchte Funktion."]}],"merke":["Bei Projekt: To-do-Liste ist die genaue JavaScript-Schreibweise wichtig.","Nutze die Lösung `const feld = document.querySelector('#aufgabe'); const liste = document.querySelector('#liste'); document.querySelector('#hinzufuegen').addEventListener('click', () => { const text = feld.value.trim(); if (!text) return; const li = document.createElement('li'); li.textContent = text; liste.appendChild(li); feld.value = ''; });` als Vergleich für deine eigene Übung."]}];if(typeof module!=="undefined"&&module.exports)module.exports=root.SDAkademieKurse["javascript"];})(typeof window!=="undefined"?window:globalThis);
